// ============================================================
// Parse Nabil Bank HTML transaction alert emails
// Extracts data from the colored table row in the email body
// Green (#1fb25a) = Credit, Red = Debit
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  // n8n Gmail node returns html under different keys depending on format
  const html = item.json.htmlBody
    || (item.json.payload && item.json.payload.body && item.json.payload.body.data)
    || item.json.body?.html
    || item.json.textHtml
    || item.json.html
    || '';

  const msgId = item.json.id || item.json.messageId || '';

  if (!html) {
    // Skip if no HTML body found
    console.log(`Message ${msgId}: no HTML body found, skipping`);
    continue;
  }

  // Match the colored transaction row
  const rowMatch = html.match(/<tr[^>]*style="[^"]*color:\s*(#1fb25a|red)[^"]*"[^>]*>([\s\S]*?)<\/tr>/i);
  if (!rowMatch) {
    console.log(`Message ${msgId}: no matching transaction row found, skipping`);
    continue;
  }

  // Extract all <td> cell contents
  const cells = [];
  const cellPattern = /<td[^>]*>\s*([\s\S]*?)\s*<\/td>/gi;
  let m;
  while ((m = cellPattern.exec(rowMatch[2])) !== null) {
    cells.push(m[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim());
  }

  if (cells.length < 5) {
    console.log(`Message ${msgId}: only ${cells.length} cells found, expected 5, skipping`);
    continue;
  }

  const [dateTime, txnType, amountStr, balanceStr, remarks] = cells;

  const type = txnType.toLowerCase().includes('credit') ? 'credit' : 'debit';
  const amount = parseFloat(amountStr.replace(/,/g, '')) || 0;
  const balance = parseFloat(balanceStr.replace(/,/g, '')) || 0;
  const date = dateTime.substring(0, 10); // "YYYY-MM-DD"

  // Auto-categorise based on remarks
  let category = 'Other';
  const rem = remarks.toLowerCase();
  if (rem.includes('fonepay') || rem.startsWith('fon:')) {
    category = 'Client Payment';
  } else if (rem.includes('salary') || rem.includes('payroll')) {
    category = 'Payroll';
  } else if (rem.includes('rent')) {
    category = 'Rent';
  } else if (rem.includes('electric') || rem.includes('bijuli') || rem.includes('light')) {
    category = 'Utilities';
  } else if (rem.includes('mpay') || rem.includes('fpqr')) {
    category = 'Supplier';
  } else if (rem.includes('tax') || rem.includes('vat') || rem.includes('ird')) {
    category = 'Tax';
  }

  results.push({
    json: {
      date,
      description: remarks,
      amountNPR: amount,
      balance,
      type,
      category,
      reference: msgId,
      source: 'nabil_auto',
      originalMessageId: msgId,
    }
  });
}

if (results.length === 0) {
  // Return a no-op item so downstream nodes don't error on empty input
  return [{ json: { _noTransactions: true } }];
}

return results;
